def cfg_eps(eps_cond, eps_uncond, w=7.5):
    # 两个分支来自同一个去噪网络，只是条件不同
    return eps_uncond + w * (eps_cond - eps_uncond)

# 训练侧：以概率 p_uncond 把条件置空，才能训出 eps_uncond 分支
