def longest_cached_prefix(trie, ids):
    # trie: 嵌套 dict，'ch' 指向子节点；返回最长命中前缀长度 p
    node, p = trie, 0
    for tok in ids:
        if tok not in node.get('ch', {}):
            break
        node = node['ch'][tok]
        p += 1
    return p

# prefill 只需计算 ids[p:]；前 p 个 token 的 KV 直接复用缓存节点
